from common import save
L = [
# --- Festivals ---
("What is Diwali?","Diwali (Deepavali) is the festival of lights, celebrated in October or November. People light lamps (diyas), burst crackers, share sweets and wear new clothes. It celebrates the victory of good over evil: Lord Rama's return to Ayodhya, and in South India Lord Krishna's victory over Narakasura.",["diwali","deepavali","festival of lights","why is diwali celebrated"]),
("What is Holi?","Holi is the festival of colours, celebrated in March at the end of winter. People throw coloured powder and water, sing and dance. The night before, Holika Dahan (a bonfire) marks the victory of Prahlad's devotion over the demoness Holika.",["holi","festival of colours","why is holi celebrated"]),
("What is Christmas?","Christmas, on 25 December, celebrates the birth of Jesus Christ. People decorate Christmas trees, sing carols, go to church, exchange gifts and share cakes. Santa Claus brings presents to children in the popular tradition.",["christmas","why is christmas celebrated","25 december festival"]),
("What is Eid ul-Fitr?","Eid ul-Fitr is the festival that ends Ramadan (Ramzan), the Islamic month of fasting from dawn to sunset. People offer special prayers, wear new clothes, give charity (zakat al-fitr) and share sweets like sheer khurma.",["eid ul fitr","ramzan","ramadan","ramzan festival","what is ramadan"]),
("What is Eid ul-Adha?","Eid ul-Adha (Bakrid) remembers Prophet Ibrahim's willingness to sacrifice his son at God's command. It comes at the end of the Hajj pilgrimage; families share meat with relatives and the poor.",["eid ul adha","bakrid","bakri eid"]),
("What is Ganesh Chaturthi?","Ganesh Chaturthi celebrates the birth of Lord Ganesha, the elephant-headed god of wisdom and new beginnings. Clay idols are worshipped for up to 10 days and then immersed in water. It is especially big in Maharashtra.",["ganesh chaturthi","vinayaka chaturthi","vinayagar chathurthi"]),
("What is Navratri and Dussehra?","Navratri is nine nights of worship of Goddess Durga, with garba and dandiya dances in Gujarat and Golu doll displays in Tamil Nadu. The tenth day, Dussehra (Vijayadashami), celebrates Rama's victory over Ravana and Durga's over Mahishasura.",["navratri","dussehra","vijayadashami","durga puja","golu","navaratri"]),
("What is Good Friday and Easter?","Good Friday remembers the crucifixion of Jesus Christ. Easter Sunday, two days later, celebrates his resurrection and is the most important Christian festival. Easter eggs are a symbol of new life.",["good friday","easter","why is good friday observed"]),
("What is Raksha Bandhan?","Raksha Bandhan celebrates the bond between brothers and sisters. The sister ties a rakhi (thread) on her brother's wrist, and he promises to protect her. It falls in August.",["raksha bandhan","rakhi"]),
("What is Guru Nanak Jayanti?","Guru Nanak Jayanti (Gurpurab) celebrates the birth of Guru Nanak Dev Ji, the founder of Sikhism. Sikhs hold prayers, processions and langar (free community meals) at gurdwaras.",["guru nanak jayanti","gurpurab","sikh festival"]),
("What is Makar Sankranti?","Makar Sankranti (14 January) marks the Sun moving into Capricorn and the harvest. It is called Pongal in Tamil Nadu, Lohri in Punjab, Uttarayan in Gujarat (kite flying) and Bihu in Assam.",["makar sankranti","sankranti","lohri","uttarayan"]),
("What is Janmashtami?","Janmashtami celebrates the birth of Lord Krishna at midnight. People fast, sing bhajans and, in Maharashtra, form human pyramids to break a pot of curd (dahi handi).",["janmashtami","krishna jayanthi","gokulashtami","dahi handi"]),
("What is Buddha Purnima?","Buddha Purnima (Vesak) celebrates the birth, enlightenment and death of Gautama Buddha, all believed to fall on the full moon of the month of Vaisakh (April or May).",["buddha purnima","vesak","buddha jayanti"]),
("What is Mahavir Jayanti?","Mahavir Jayanti celebrates the birth of Lord Mahavira, the 24th Tirthankara of Jainism, who taught non-violence (ahimsa), truth and non-attachment.",["mahavir jayanti","jain festival"]),
# --- Exams and careers ---
("How to become an IAS officer?","To become an IAS officer: finish any bachelor's degree, then clear the UPSC Civil Services Exam, which has three stages: Prelims (objective), Mains (nine written papers) and an Interview. You must be at least 21. Many start preparing with NCERT books from class 6 to 12 and reading a newspaper daily.",["how to become ias","ias officer","upsc exam","civil services exam","how to become collector"]),
("How to become a doctor in India?","To become a doctor: take Biology, Physics and Chemistry in classes 11 and 12, clear the NEET exam, then study MBBS for 5.5 years (including a 1-year internship). After that you can specialise with an MD or MS through NEET-PG.",["how to become a doctor","mbbs","what is neet","neet exam"]),
("How to become an engineer?","To become an engineer: take Maths, Physics and Chemistry in classes 11 and 12, then clear an entrance exam such as JEE Main (for NITs), JEE Advanced (for IITs) or a state exam like TNEA, and study a 4-year B.E. or B.Tech degree.",["how to become an engineer","jee exam","what is jee","iit entrance"]),
("How to become a software developer?","To become a software developer: learn one language well (Python or JavaScript are good starts), practise with small projects, learn data structures and algorithms, use Git and GitHub, and build a portfolio. A B.Tech or BCA/MCA helps, but many developers are self-taught.",["how to become a software developer","how to become a programmer","software engineer career","how to become a coder"]),
("How to become a pilot?","To become a commercial pilot in India: study Physics and Maths in class 12, pass a DGCA Class 2 then Class 1 medical, join a flying school, log about 200 flying hours and clear the DGCA exams to get a Commercial Pilot Licence (CPL).",["how to become a pilot","pilot career","commercial pilot licence"]),
("How to become a chartered accountant?","To become a Chartered Accountant (CA): register with ICAI after class 12, clear CA Foundation, then CA Intermediate, complete 2 to 3 years of articleship training, and clear CA Final.",["how to become a ca","chartered accountant","ca course"]),
("How to become a lawyer?","To become a lawyer in India: after class 12 take CLAT (or another law entrance) for a 5-year integrated LLB, or do a 3-year LLB after any degree. Then clear the All India Bar Exam to practise.",["how to become a lawyer","clat exam","llb"]),
("How to become a teacher?","To become a school teacher in India: finish a degree, then a B.Ed (2 years), and clear a Teacher Eligibility Test such as CTET or TET. For college teaching, you need a master's degree and UGC-NET.",["how to become a teacher","b ed","ctet"]),
("How to become a scientist?","To become a scientist: study science deeply, do a BSc or B.Tech, then an MSc and a PhD in your field. Institutes like IISc, IISER and ISRO hire researchers. Curiosity, reading and doing experiments matter most.",["how to become a scientist","career in science","how to join isro"]),
("How to become an astronaut?","To become an astronaut you usually need a degree in science, engineering or medicine, or experience as a test pilot, excellent health and fitness, and years of training. India's Gaganyaan astronauts were chosen from Indian Air Force test pilots.",["how to become an astronaut","astronaut career"]),
("How to become a YouTuber?","To become a YouTuber: choose a topic you love, plan short and useful videos, record with a phone in good light with clear sound, edit with a free app, upload regularly and reply to comments. YouTube's minimum age is 13.",["how to become a youtuber","how to start a youtube channel"]),
# --- Study and life skills ---
("How to manage time?","Time management tips: write a daily to-do list, do the hardest task first, break big jobs into small steps, use the Pomodoro method (25 minutes of work, 5 minutes of break), keep your phone away while working and get 8 hours of sleep.",["time management","how to manage time","time management tips","pomodoro technique"]),
("How to stop procrastinating?","To stop procrastinating: start with just 2 minutes of the task, remove distractions, set a small clear goal, reward yourself after finishing, and remember that starting is the hardest part.",["procrastination","how to stop procrastinating","how to stop being lazy"]),
("How to improve memory?","To improve memory: revise at spaced intervals (after 1 day, 3 days, 1 week), test yourself instead of re-reading, teach the topic to someone, use mnemonics and pictures, sleep well and exercise.",["how to improve memory","memory tips"]),
("How to prepare for exams?","Exam tips: make a timetable, study a little every day, solve past papers, make short notes for revision, practise writing answers within time, sleep well the night before and eat a light breakfast.",["how to prepare for exams","exam preparation"]),
("How to speak confidently?","To speak confidently: prepare and practise aloud, stand straight and make eye contact, speak slowly, pause instead of saying 'umm', and start with small groups before big audiences.",["how to speak confidently","public speaking tips","stage fear"]),
("How to improve handwriting?","To improve handwriting: hold the pen lightly, sit straight, write slowly, keep letters the same size and spacing, and practise one page daily with a four-line notebook.",["how to improve handwriting","handwriting tips"]),
("How to make friends?","To make friends: smile and say hello, ask people about themselves and listen, join clubs or teams, be kind and helpful, and be yourself. Good friendships grow with time.",["how to make friends","making friends"]),
("How to control anger?","To control anger: stop and take slow deep breaths, count to ten, walk away for a while, then say how you feel calmly. Exercise and enough sleep also help.",["how to control anger","anger management"]),
# --- Online safety ---
("What is cyberbullying?","Cyberbullying is bullying through phones or the internet: mean messages, rumours, embarrassing photos or leaving someone out on purpose. If it happens: don't reply, take screenshots, block the person and tell a trusted adult. In India you can report it at cybercrime.gov.in or call 1930.",["cyberbullying","cyber bullying","online bullying"]),
("How to make a strong password?","A strong password is at least 12 characters and mixes capital and small letters, numbers and symbols. A passphrase like 'Mango!Rain7Tiger' is strong and easy to remember. Use a different password for each account, never share it, and turn on two-step verification.",["strong password","how to make a strong password","password tips","good password"]),
("What is a cyber crime helpline number in India?","In India, call 1930 or visit cybercrime.gov.in to report online fraud and cyber crime. Report money fraud quickly, because the money can sometimes be blocked.",["cyber crime helpline","cyber crime number","1930","how to report cyber crime"]),
("What is digital footprint?","Your digital footprint is the trail you leave online: posts, photos, comments, searches and likes. It can be seen by schools and employers later, so post thoughtfully.",["digital footprint"]),
# --- Disasters and safety ---
("What is an earthquake?","An earthquake is the shaking of the ground when rocks along a fault in Earth's crust suddenly slip. It is measured on the Richter or moment magnitude scale with a seismograph. During one: drop, cover under a sturdy table and hold on; stay away from windows.",["earthquake","what causes an earthquake","what to do during an earthquake","earthquake safety"]),
("What is a tsunami?","A tsunami is a series of huge sea waves caused by an undersea earthquake, volcano or landslide. The 2004 Indian Ocean tsunami hit Tamil Nadu and other coasts. If the sea suddenly pulls back, move to high ground at once.",["tsunami","what causes a tsunami","2004 tsunami"]),
("What is a cyclone?","A cyclone is a huge storm spinning around a low-pressure centre, with strong winds and heavy rain. They form over warm seas: called hurricanes in the Atlantic and typhoons in the Pacific. The India Meteorological Department (IMD) names and tracks them.",["cyclone","hurricane","typhoon","what is a hurricane","cyclone safety"]),
("What is a flood?","A flood happens when water overflows onto normally dry land, from heavy rain, overflowing rivers, dam releases or cyclones. Stay safe by moving to higher ground, not walking or driving through flowing water, and switching off electricity.",["flood","floods","what causes floods","flood safety"]),
("What is a landslide?","A landslide is rock, soil and debris sliding down a slope, often after heavy rain, earthquakes or cutting of trees. Hilly areas like the Western Ghats and the Himalayas are prone to them.",["landslide","landslides"]),
("What is a drought?","A drought is a long period with much less rain than normal, causing water shortage and crop failure. Rainwater harvesting, saving water and drip irrigation help reduce its effects.",["drought","droughts"]),
("What is a volcano?","A volcano is an opening in Earth's crust where molten rock (magma), ash and gases erupt. When magma reaches the surface it's called lava. India's only active volcano is Barren Island in the Andaman Sea.",["volcano","volcanoes","active volcano in india"]),
("What are fire safety tips?","Fire safety: if clothes catch fire, stop, drop and roll. Crawl low under smoke. Never use a lift during a fire. Keep a fire extinguisher and learn PASS (Pull, Aim, Squeeze, Sweep). In India, call 101 for the fire service.",["fire safety","fire safety tips","what to do in a fire","stop drop and roll"]),
("What is first aid for a snake bite?","For a snake bite: keep the person calm and still, keep the bitten limb below heart level, remove rings and tight things, and rush to a hospital for anti-venom. Do not cut the wound, suck the venom or tie a tight tourniquet.",["snake bite","snake bite first aid","what to do if a snake bites"]),
("What is first aid for a dog bite?","For a dog bite: wash the wound with soap and running water for 15 minutes, apply an antiseptic and see a doctor quickly for the rabies vaccine. Rabies is fatal once symptoms start, but completely preventable with the vaccine.",["dog bite","dog bite first aid","rabies"]),
("What is first aid for a nosebleed?","For a nosebleed: sit up, lean forward (not back), pinch the soft part of the nose for 10 minutes and breathe through the mouth. See a doctor if it lasts more than 20 minutes.",["nosebleed","nose bleeding","nose bleed first aid"]),
("What is first aid for fainting?","If someone faints: lay them on their back and raise their legs about 30 cm, loosen tight clothing and give fresh air. If they don't wake up within a minute, call 108.",["fainting","first aid for fainting","someone fainted"]),
("What is heat stroke?","Heat stroke is when the body overheats (above 40 °C) in hot weather: hot dry skin, confusion and fainting. Move the person to shade, cool them with wet cloths and a fan, give water if awake and call 108. Prevent it by drinking water and avoiding the midday sun.",["heat stroke","sunstroke","heatstroke"]),
# --- Environment ---
("What is noise pollution?","Noise pollution is unwanted loud sound from traffic, horns, loudspeakers, crackers and machines. Sound is measured in decibels (dB); above about 85 dB for long periods can damage hearing.",["noise pollution","decibel"]),
("What is soil pollution?","Soil pollution is harmful chemicals and waste in the soil, from too much pesticide and fertiliser, plastics and industrial waste. It lowers crop yields and enters our food.",["soil pollution","land pollution"]),
("What is acid rain?","Acid rain is rain made acidic by sulphur dioxide and nitrogen oxides from burning coal and fuel. It harms plants, fish and buildings; it has damaged the marble of the Taj Mahal.",["acid rain"]),
("What is deforestation?","Deforestation is cutting down forests for farming, wood, mining or cities. It causes soil erosion, floods, loss of wildlife and more carbon dioxide in the air. Planting trees (afforestation) helps.",["deforestation","effects of deforestation","afforestation"]),
("What is a carbon footprint?","A carbon footprint is the total greenhouse gas your activities cause. Reduce it by walking, cycling or taking the bus, saving electricity, eating less wasted food and reusing things.",["carbon footprint"]),
("What is rainwater harvesting?","Rainwater harvesting is collecting rain from rooftops into tanks or letting it soak into the ground to refill wells. Tamil Nadu made it compulsory for buildings in 2003.",["rainwater harvesting"]),
("What are the 3 Rs?","The 3 Rs of waste are Reduce (use less), Reuse (use again) and Recycle (make new things from old). Some add Refuse and Repair too.",["3 rs","reduce reuse recycle","three rs"]),
("What is composting?","Composting turns kitchen and garden waste (vegetable peels, leaves) into rich manure. Mix wet and dry waste in a pit or bin, keep it moist and turn it weekly; it is ready in 6 to 8 weeks.",["composting","how to make compost","compost"]),
("What is wet and dry waste?","Wet waste is kitchen waste that rots, like food and peels: it can be composted. Dry waste is paper, plastic, metal and glass: it can be recycled. Keep them in separate bins (green for wet, blue for dry).",["wet waste","dry waste","waste segregation"]),
("When is World Environment Day?","World Environment Day is on 5 June. Other days: Earth Day 22 April, World Water Day 22 March, World Wildlife Day 3 March, Ozone Day 16 September.",["world environment day","earth day","world water day"]),
# --- Money basics ---
("What is the difference between needs and wants?","Needs are things you must have to live, like food, water, shelter, clothes and education. Wants are nice to have, like toys, games and eating out. Smart spending covers needs first.",["needs and wants","difference between needs and wants"]),
("How to open a bank account?","To open a bank account in India, visit a bank with an Aadhaar card, a PAN card (or Form 60), a photo and address proof, and fill in the form. Minors can open accounts with a parent. Many banks let you open one online by video KYC.",["how to open a bank account","bank account","minor bank account"]),
("What is interest?","Interest is money paid for using money. The bank pays you interest on savings, and you pay interest when you borrow a loan. Simple interest = P × R × T ÷ 100.",["what is interest","interest on savings"]),
("What is a credit card and a debit card?","A debit card spends money already in your bank account. A credit card borrows money from the bank, which you must repay by the due date or pay high interest (often 36 to 42% a year).",["debit card","credit card","difference between debit card and credit card"]),
]
save("life", "Festivals, careers, safety, environment and money", L)
